    #[test]
    fn test_append_empty() {
        let v: Vec<u64> = Vec::new();
        let out = append(&v, 42);
        assert_eq!(out.len(), 1);
        assert_eq!(out[0], 42);
    }

    #[test]
    fn test_append_non_empty() {
        let v = vec![1, 2, 3];
        let out = append(&v, 99);
        assert_eq!(out.len(), 4);
        assert_eq!(&out[..3], &[1, 2, 3]);
        assert_eq!(out[3], 99);
        // Ensure original is unchanged
        assert_eq!(v, vec![1, 2, 3]);
    }

    #[test]
    fn test_multiple_appends() {
        let mut v = vec![5];
        for &x in &[6, 7, 8, 9] {
            v = append(&v, x);
        }
        assert_eq!(v, vec![5, 6, 7, 8, 9]);
    }
